import { isDeepStrictEqual } from 'node:util';
// Diagnostic copy only. Immediate bounded markers distinguish predicate work
// from mismatch formatting; comparison truth and argument order are unchanged.
let boundedComparisonEvents = 0;
function boundedComparisonStage(stage) {
  if (boundedComparisonEvents >= 32) return;
  boundedComparisonEvents++;
  process.stderr.write('# SOLO_COUCH_COMPARE ' + boundedComparisonEvents + ' ' + stage + '\n');
}
function boundedComparisonLabel(value) {
  if (value === null) return 'null';
  if (value === undefined) return 'undefined';
  if (typeof value !== 'object' && typeof value !== 'function') return String(value).slice(0, 80);
  return [value.tagName, value.id].filter((part) => typeof part === 'string')
    .map((part) => part.slice(0, 80)).join('#') || typeof value;
}
function boundedIdentity(actual, expected, message) {
  boundedComparisonStage('identity-begin');
  const same = Object.is(actual, expected);
  boundedComparisonStage('identity-result-' + same);
  if (same) return;
  boundedComparisonStage('identity-bounded-failure');
  assert.ok(false, (message ?? 'Strict identity mismatch.') +
    ' Actual: ' + boundedComparisonLabel(actual) + '; expected: ' + boundedComparisonLabel(expected) + '.');
}
function boundedDOMArrayEqual(actual, expected, message) {
  boundedComparisonStage('dom-array-deep-comparison-begin');
  const same = isDeepStrictEqual(actual, expected);
  boundedComparisonStage('dom-array-deep-comparison-result-' + same);
  if (same) return;
  const label = (value) => Array.isArray(value)
    ? 'Array(' + value.length + ')[' + value.slice(0, 4).map(boundedComparisonLabel).join(',') + ']'
    : boundedComparisonLabel(value);
  boundedComparisonStage('dom-array-bounded-failure');
  assert.ok(false, (message ?? 'Deep strict DOM array mismatch.') +
    ' Actual: ' + label(actual) + '; expected: ' + label(expected) + '.');
}

