import test from 'node:test';
import assert from 'node:assert/strict';
// Diagnostic only: retain exact strict identity with bounded mismatch output.
let identityStages = 0;
function identityStage(stage) {
  if (identityStages < 32) process.stderr.write('# SOLO_IDENTITY ' + (++identityStages) + ' ' + stage + '\n');
}
function boundedIdentity(actual, expected, message) {
  identityStage('predicate-begin');
  const same = Object.is(actual, expected);
  identityStage('predicate-result-' + same);
  if (same) return;
  const label = (value) => {
    if (value === null) return 'null';
    if (value === undefined) return 'undefined';
    if (typeof value !== 'object' && typeof value !== 'function') return String(value).slice(0, 80);
    return [value.tagName, value.id].filter((x) => typeof x === 'string').map((x) => x.slice(0, 80)).join('#') || typeof value;
  };
  identityStage('bounded-failure');
  assert.ok(false, (message ?? 'Strict identity mismatch.') + ' Actual: ' + label(actual) + '; expected: ' + label(expected) + '.');
}
import { setTimeout as nextTask } from 'node:timers/promises';
import { AUDIO_PREFERENCES_KEY } from '../audio-preferences.mjs';
import { DISPLAY_PREFERENCES_KEY } from '../display-preferences.mjs';
