    await nextTask(0);
    assert.deepEqual(f.read(), stale);
    assert.deepEqual(f.storage.writes, writes);
    assert.deepEqual([...f.storage.map], records);
    f.unchanged({ advanceFrame: false, expectedFocus: focus });
    assert.deepEqual(f.effects(), effects);
